package com.lexorion.gateway;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import org.slf4j.MDC;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(Ordered.HIGHEST_PRECEDENCE+1) public class CorrelationIdFilter extends OncePerRequestFilter{public static final String HEADER="X-Correlation-ID";@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String v=r.getHeader(HEADER),id=v!=null&&v.matches("[A-Za-z0-9._:-]{1,64}")?v:UUID.randomUUID().toString();s.setHeader(HEADER,id);MDC.put("correlationId",id);HttpServletRequest wrapped=new HttpServletRequestWrapper(r){@Override public String getHeader(String n){return HEADER.equalsIgnoreCase(n)?id:super.getHeader(n);}@Override public Enumeration<String> getHeaders(String n){return HEADER.equalsIgnoreCase(n)?Collections.enumeration(List.of(id)):super.getHeaders(n);}@Override public Enumeration<String> getHeaderNames(){List<String> names=Collections.list(super.getHeaderNames());if(names.stream().noneMatch(HEADER::equalsIgnoreCase))names.add(HEADER);return Collections.enumeration(names);}};try{c.doFilter(wrapped,s);}finally{MDC.remove("correlationId");}}}
